css_rules:
:root { --vh: 1vh; --header-font: "Feature Display"; --ref-screen-width: 1440; --site-padding-x: min(60px, calc(40 * 100vw / var(--ref-screen-width))); --site-padding-y: var(--site-padding-x); --color-white: #fbfff4; --color-dark-green: #203727; --color-light-green: #e0ffab; --content-width: calc(100vw - var(--site-padding-x) * 2); --content-unit: calc(var(--content-width) / var(--ref-screen-width)); --h3: max(55px, calc(var(--content-unit) * 80)); --sub2: max(18px, calc(var(--content-unit) * 18)); --btn2: max(16px, calc(var(--content-unit) * 18)); }
h3 { font-family:var(--header-font);font-weight:200;margin:0;padding:0;line-height:1 }
h3 { font-size:var(--h3) }
.sub2 { font-family:var(--header-font);font-weight:400 }
.sub2 { font-size:var(--sub2) }
.btn2 { font-family:var(--header-font);font-weight:400;font-size:var(--btn2) }
@font-face { font-family:Feature Display;font-weight:200;font-style:normal;font-display:block;src:url(/assets/fonts/FeatureDisplay-Extralight.woff2) format("woff2") }
@font-face { font-family:Feature Display;font-weight:400;font-style:normal;font-display:block;src:url(/assets/fonts/FeatureDisplay-Regular.woff2) format("woff2") }
@font-face { font-family:Britti Sans;font-weight:400;font-style:normal;font-display:block;src:url(/assets/fonts/BrittiSans-Regular.woff2) format("woff2") }
@font-face { font-family:Britti Sans;font-weight:300;font-style:normal;font-display:block;src:url(/assets/fonts/BrittiSans-Light.woff2) format("woff2") }
@font-face { font-family:Britti Sans;font-weight:600;font-style:normal;font-display:block;src:url(/assets/fonts/BrittiSans-Semibold.woff2) format("woff2") }
html { width:100%;height:100%;color:var(--color-white);line-height:1.4 }
body { position:fixed;width:100%;height:100%;overflow:hidden;margin:0;overscroll-behavior:none;touch-action:none }
* { box-sizing:border-box }
#home-join { padding-bottom:calc(var(--vh) * 0) }
#home-join .section__content { height:calc(var(--vh) * 100) }
#home-join .title-wrapper { position:absolute;left:0;top:50%;display:flex;flex-direction:column;align-items:center;justify-content:center;height:40%;text-align:center }
#home-join .subtitle { letter-spacing:.18px }
#home-join__buttons { position:relative;margin-top:1em;display:flex;flex-direction:row;align-items:center;gap:1.8em;height:2.5em;line-height:2.6em;padding:0 1.5em;color:var(--color-dark-green);border-radius:2em;overflow:hidden }
#home-join__buttons span { transition:transform .18s }
#home-join__buttons a { position:relative;display:block;height:100%;cursor:pointer;color:inherit }
#home-join__buttons a span { display:inline-block }
#home-join__buttons a:hover span { transform:scale(1.03) }
#home-join__buttons:before { --width: 0px;position:absolute;content:"";top:0;left:50%;transform:translate(-50%);width:100%;height:100%;background:var(--color-light-green) }
.section { position:relative }
.section__content { position:relative;display:flex;flex-direction:column;justify-content:center;align-items:flex-start;padding:var(--site-padding-y) var(--site-padding-x) }
.title-wrapper { width:100%;display:flex;flex-direction:column;align-items:flex-start;gap:1em;justify-content:center;align-items:center }
.title { text-shadow:0 0 .12em rgba(0,0,0,.3) }
.subtitle { text-shadow:0 0 1em rgba(0,0,0,.3) }
@media (max-width: 991.98px) {
#home-join .title { text-align:center;display:flex;flex-direction:column;align-items:center;justify-content:center }
}
